const menu=document.querySelector('.menu');const nav=document.querySelector('#nav');const header=document.querySelector('.site-header');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu?.setAttribute('aria-expanded','false');nav.classList.remove('open')}));const onScroll=()=>header?.classList.toggle('scrolled',scrollY>48);onScroll();addEventListener('scroll',onScroll,{passive:true});const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced&&'IntersectionObserver'in window){const items=document.querySelectorAll('.statement h2,.service-feature,.service-list article,.approach li,.assurance-list article,.work-item,.contact-side');items.forEach(el=>el.classList.add('reveal'));const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});items.forEach(el=>observer.observe(el))}
